import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";
import "./Profile.css"; // custom styles

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software engineer",
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software engineer"
          });
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem("token");
    if (!token) return;

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: {
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("✅ Profile updated successfully!");
      } else {
        setMessage("❌ Failed to update profile");
      }
    } catch (err) {
      setMessage("⚠️ Network error. Try again later.");
    }
  };

  if (loading) return <p className="loading-text">Loading profile...</p>;

  return (
    <div className="profile-container">
      {/* Left Sidebar (can be replaced with your real sidebar) */}
      <aside className="sidebar">
        <h3>Menu</h3>
        <ul>
          <li>Dashboard</li>
          <li className="active">Profile</li>
          <li>Jobs</li>
          <li>Settings</li>
        </ul>
      </aside>

      {/* Right Content */}
      <div className="profile-content">
        <div className="profile-header">
          <div>
            <h2>My Profile</h2>
            <p>Manage your personal information</p>
          </div>
          <img 
            src="https://illustrations.popsy.co/gray/person-working-on-computer.svg" 
            alt="Profile illustration" 
            className="profile-illustration"
          />
        </div>

        <form onSubmit={handleSubmit} className="profile-form">
          <div className="form-group mb-3">
            <label className="form-label">Full Name</label>
            <input
              type="text"
              className="form-control"
              name="fullName"
              value={profile.fullName}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group mb-3">
            <label className="form-label">Email Address</label>
            <input
              type="email"
              className="form-control"
              name="email"
              value={profile.email}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group mb-3">
            <label className="form-label">Phone Number</label>
            <input
              type="tel"
              className="form-control"
              name="phone"
              value={profile.phone}
              onChange={handleChange}
            />
          </div>

          <div className="form-group mb-3">
            <label className="form-label">Role</label>
            <input
              type="text"
              className="form-control"
              value={profile.role}
              readOnly
            />
          </div>

          <div className="form-group mb-3">
            <label className="form-label">Bio</label>
            <textarea
              className="form-control"
              name="bio"
              rows="3"
              value={profile.bio}
              onChange={handleChange}
            ></textarea>
          </div>

          <button type="submit" className="btn btn-primary px-4">
            Update Profile
          </button>
        </form>

        {message && <p className="update-msg">{message}</p>}
      </div>
    </div>
  );
}
